flowSteps.label:
return $users->map(function (User $user): ?array {
    $licenseNumber = $this->extractLicenseNumber($user->licencia);
    if ($licenseNumber === null) {
        return null;
    }
    return ['key' => sprintf('%s:%02d', (string) $user->municipio_id, $licenseNumber), 'user' => $user];
})->filter()->groupBy("key")->map(function (Collection $items, string $groupKey): ?array {
    $members = $items->pluck('user')->filter(fn($user): bool => $user instanceof User)->values();
    if ($members->count() < 2) {
        return null;
    }
    /** @var User $keeper */
    $keeper = $members->sortBy([fn(User $user): int => -$this->calculateKeeperScore($user), fn(User $user): int => $user->id])->first();
    $duplicates = $members->reject(fn(User $user): bool => $user->is($keeper))->values()->all();
    if ($duplicates === []) {
        return null;
    }
    return ['group_key' => $groupKey, 'municipio' => (string) ($keeper->municipio?->nombre ?? '-'), 'preferred_license' => $this->resolvePreferredLicense($members), 'keeper' => $keeper, 'duplicates' => $duplicates, 'members' => $members];
})->filter()->values()

